using System;

namespace Tsumo.Tests
{
    public static class Node_modules_Tsumo_engine_src_utils_mime
    {
        public static Func<string, string> contentTypeForPath
        {
            get;
            private set;
        } = default(Func<string, string>)!;
        private static readonly System.Lazy<object?> __tsonic_module_initialization = new System.Lazy<object?>(() => __tsonic_module_init_core());
        private static object? __tsonic_module_init_core()
        {
            contentTypeForPath = (string path) =>
            {
                string lower = Tsonic.CSharp.Js.String.toLowerCase(path);
                if (Tsonic.CSharp.Js.String.endsWith(lower, ".html") || Tsonic.CSharp.Js.String.endsWith(lower, ".htm"))
                {
                    return "text/html; charset=utf-8";
                }
                if (Tsonic.CSharp.Js.String.endsWith(lower, ".css"))
                {
                    return "text/css; charset=utf-8";
                }
                if (Tsonic.CSharp.Js.String.endsWith(lower, ".js"))
                {
                    return "text/javascript; charset=utf-8";
                }
                if (Tsonic.CSharp.Js.String.endsWith(lower, ".json"))
                {
                    return "application/json; charset=utf-8";
                }
                if (Tsonic.CSharp.Js.String.endsWith(lower, ".xml"))
                {
                    return "application/xml; charset=utf-8";
                }
                if (Tsonic.CSharp.Js.String.endsWith(lower, ".txt"))
                {
                    return "text/plain; charset=utf-8";
                }
                if (Tsonic.CSharp.Js.String.endsWith(lower, ".svg"))
                {
                    return "image/svg+xml";
                }
                if (Tsonic.CSharp.Js.String.endsWith(lower, ".png"))
                {
                    return "image/png";
                }
                if (Tsonic.CSharp.Js.String.endsWith(lower, ".jpg") || Tsonic.CSharp.Js.String.endsWith(lower, ".jpeg"))
                {
                    return "image/jpeg";
                }
                if (Tsonic.CSharp.Js.String.endsWith(lower, ".gif"))
                {
                    return "image/gif";
                }
                if (Tsonic.CSharp.Js.String.endsWith(lower, ".webp"))
                {
                    return "image/webp";
                }
                if (Tsonic.CSharp.Js.String.endsWith(lower, ".ico"))
                {
                    return "image/x-icon";
                }
                if (Tsonic.CSharp.Js.String.endsWith(lower, ".woff"))
                {
                    return "font/woff";
                }
                if (Tsonic.CSharp.Js.String.endsWith(lower, ".woff2"))
                {
                    return "font/woff2";
                }
                return "application/octet-stream";
            };
            return null;
        }
        public static void __tsonic_module_init()
        {
            _ = __tsonic_module_initialization.Value;
        }
    }
}
